/* Arc DNA — soft pastel gradients, macOS-glass panels, bubbly corners */
.theme-arc-dna {
  --bg: oklch(0.989 0.024 99.1);
  --surface: oklch(1 0 0 / 62%);
  --surface-2: oklch(1 0 0 / 42%);
  --fg: oklch(0.25 0.04 300);
  --fg-muted: oklch(0.5 0.04 300);
  --accent: oklch(0.499 0.274 269.3);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.68 0.15 240);
  --line: oklch(1 0 0 / 55%);
  --success: oklch(0.7 0.14 155);
  --warning: oklch(0.817 0.164 75.9);
  --danger: oklch(0.650 0.226 21.5);

  --radius: 1.125rem;
  --radius-sm: 0.75rem;
  --radius-lg: 1.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px oklch(0.3 0.05 300 / 8%), inset 0 1px 0 oklch(1 0 0 / 60%);
  --shadow-2: 0 12px 32px -12px oklch(0.35 0.08 300 / 28%), inset 0 1px 0 oklch(1 0 0 / 65%);
  --shadow-3: 0 30px 70px -28px oklch(0.35 0.08 300 / 38%);
  --glow: 0 0 0 4px color-mix(in oklab, var(--accent) 25%, transparent);

  --border-width: 1px;
  --blur-amount: 24px;

  --font-display: "Varela Round", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.025em;
  --label-transform: none;
  --label-tracking: 0.01em;

  background-color: var(--bg);
  background-image:
    radial-gradient(55% 50% at 10% 5%, oklch(0.88 0.11 330 / 85%), transparent 70%),
    radial-gradient(50% 45% at 90% 15%, oklch(0.88 0.1 250 / 75%), transparent 70%),
    radial-gradient(60% 50% at 60% 95%, oklch(0.9 0.1 190 / 70%), transparent 70%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-arc-dna h1,
.theme-arc-dna h2,
.theme-arc-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

.theme-arc-dna section > div,
.theme-arc-dna article,
.theme-arc-dna dialog {
  backdrop-filter: blur(var(--blur-amount)) saturate(160%);
  -webkit-backdrop-filter: blur(var(--blur-amount)) saturate(160%);
}

/* signature */
.theme-arc-dna { background-image: radial-gradient(circle at 15% 12%, oklch(0.9 0.06 300 / 45%), transparent 35%), radial-gradient(circle at 85% 25%, oklch(0.9 0.05 220 / 40%), transparent 35%); }
.theme-arc-dna { --font-ui: var(--font-display); }
.theme-arc-dna button { transition: transform 160ms cubic-bezier(0.34, 1.56, 0.64, 1); }
.theme-arc-dna button:hover { transform: scale(1.05) rotate(-0.5deg); }

/* alt mode: auto-derived dark variant */
.theme-arc-dna.alt-mode {
  --bg: oklch(0.145 0.024 99.1);
  --surface: oklch(0.185 0.024 99.1);
  --surface-2: oklch(0.225 0.024 99.1);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image: none;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
